import {editEffectOngoing} from './effect-ongoing.js';
import {effectImmunityRoles,editEffectImmunity} from './effect-immunity.js';
import {effectTagRoles,editEffectTagRequirements} from './effect-tag-requirements.js';
// Uses the structured editor's existing copy/validate/Undo/save transaction.
export function effectTagEditor(document,doc,index,edit,{immunity=false,ongoing=false}={}){
 const owner=index===null?doc.data:doc.data.modifiers[index],key=ongoing?'ongoingRequirements':immunity?'immunity':index===null?'applicationRequirements':'tagRequirements',read=data=>index===null?data[key]:data.modifiers[index][key],write=(data,value)=>ongoing?editEffectOngoing(data,value):immunity?editEffectImmunity(data,value):editEffectTagRequirements(data,index,value),value=owner[key],root=document.createElement('fieldset'),legend=document.createElement('legend'),toggle=document.createElement('button');root.dataset.effectTagRequirements=ongoing?'ongoing':immunity?'immunity':index===null?'application':String(index);legend.textContent=ongoing?'지속 활성 태그 조건':immunity?'들어오는 효과 면역':index===null?'효과 적용 태그 조건':'변경 항목 태그 조건';root.append(legend);toggle.type='button';toggle.textContent=value?'조건 제거':'조건 추가';toggle.dataset.effectTagToggle='';toggle.onclick=()=>edit(data=>write(data,value?undefined:immunity?{effect:{any:['Status']}}:{source:{all:[],any:[],none:[]}}));root.append(toggle);if(!value)return root;
 const labels={effect:'들어오는 효과',source:'출처',target:'대상',instigator:'발동자',causer:'원인'};
 for(const role of immunity?effectImmunityRoles:effectTagRoles){const group=document.createElement('div'),title=document.createElement('strong');title.textContent=labels[role];group.append(title);for(const [mode,label]of [['all','모두 필요'],['any','하나 이상'],['none','차단']]){const line=document.createElement('label'),input=document.createElement('input');input.value=(value[role]?.[mode]||[]).join(', ');input.dataset.effectTagRole=role;input.dataset.effectTagMode=mode;input.setAttribute('aria-label',labels[role]+' '+label);line.append(label,input);group.append(line);input.onchange=()=>edit(data=>{const requirements=structuredClone(read(data));requirements[role]??={};requirements[role][mode]=input.value.split(',').map(s=>s.trim()).filter(Boolean);write(data,requirements);});}
 const line=document.createElement('label'),exact=document.createElement('input');exact.type='checkbox';exact.checked=!!value[role]?.exact;exact.dataset.effectTagExact=role;exact.setAttribute('aria-label',labels[role]+' 정확한 태그');line.append('정확한 태그',exact);group.append(line);exact.onchange=()=>edit(data=>{const requirements=structuredClone(read(data));requirements[role]??={};requirements[role].exact=exact.checked;write(data,requirements);});root.append(group);}
 return root;
}
